.card { font-family: Segoe UI, Tahoma, sans-serif; margin: 0; }
.card-container {
    display: flex; justify-content: center; align-items: center;
    min-height: 100vh; width: 100%;
    background: linear-gradient(135deg,#020111,#20124d);
    padding: 12px; box-sizing: border-box;
}
.card-front, .card-back {
    background: #0d0221e6;
    border-radius: 24px; padding: 35px 28px;
    width: 100%; max-width: 420px;
    text-align: center;
    box-shadow: 0 0 40px rgba(224,176,255,0.3);
    border: 1px solid rgba(255,255,255,0.15);
    position: relative; overflow: hidden;
}
.icon { font-size: 48px; margin-bottom: 6px; position: relative; z-index: 1; }
.word { font-size: 34px; font-weight: bold; color: #fff; margin: 8px 0; position: relative; z-index: 1; line-height: 1.4; }
.arabic { font-size: 28px; font-weight: bold; color: #fff; margin: 6px 0 10px; position: relative; z-index: 1; line-height: 1.4; direction: rtl; }
.suffix { font-size: 11px; color: #e0b0ff; opacity: 0.65; margin: 3px 0; position: relative; z-index: 1; }
.divider { width: 50px; height: 2px; background: #fff; opacity: 0.3; margin: 8px auto; border-radius: 2px; position: relative; z-index: 1; }
.deck-label { font-size: 9px; color: #fff; opacity: 0.35; margin-top: 16px; border-top: 1px solid #fff22; padding-top: 8px; position: relative; z-index: 1; }
.card-front::after{content:'';position:absolute;width:100%;height:100%;top:0;left:0;background:radial-gradient(1px 1px at 20% 30%,#fff,transparent),radial-gradient(1px 1px at 40% 70%,#fff,transparent),radial-gradient(1.5px 1.5px at 60% 20%,#fff,transparent),radial-gradient(1px 1px at 80% 50%,#fff,transparent),radial-gradient(1px 1px at 30% 80%,#fff,transparent),radial-gradient(1.5px 1.5px at 70% 40%,#fff,transparent);background-size:150px 150px;pointer-events:none}

